window.frases=[{t:"Cuando una puerta de felicidad se cierra, otra se abre; pero muchas veces miramos tanto la cerrada que no vemos la abierta.",a:"Helen Keller"},{t:"Arriesgarse es perder moment\xE1neamente el equilibrio; no arriesgarse es perderlo para siempre.",a:"S\xF8ren Kierkegaard"},{t:"Amar a alguien significa verle el rostro tal como lo so\xF1\xF3 Dios.",a:"Fi\xF3dor Dostoyevski"},{t:"Cada error es una clase pagada; no repitas el curso gratis.",a:"An\xF3nimo"},{t:"Mejor es el fin de una cosa que su principio; mejor la paciencia que la soberbia.",a:"Proverbio hebreo"},{t:"Se puede resistir al ej\xE9rcito invasor, pero no a las ideas cuyo momento ha llegado.",a:"Sim\xF3n Bol\xEDvar"},{t:"Cambiar el mundo, compa\xF1era, es la \xFAnica manera de conservarlo.",a:"Mercedes Sosa"},{t:"El que comete un error y no lo corrige, comete otro error.",a:"Confucio"},{t:"Solo cuando talles el \xFAltimo \xE1rbol comprender\xE1s que no se puede comer dinero.",a:"Proverbio cree"},{t:"Cuando veas a alguien bueno, piensa en imitarlo; cuando veas a alguien malo, examina tus propias faltas.",a:"Confucio"},{t:"La felicidad de tu vida depende de la calidad de tus pensamientos.",a:"Marco Aurelio"},{t:"No puedes volver atr\xE1s y empezar de nuevo, pero puedes empezar ahora y hacer un nuevo final.",a:"C. S. Lewis"},{t:"Lo que uno puede imaginar, otro lo puede crear; y quien sue\xF1a, ya empez\xF3.",a:"Julio Verne"},{t:"El que lee mucho y anda mucho, ve mucho y sabe mucho.",a:"Miguel de Cervantes"},{t:"El comienzo es la parte m\xE1s importante del trabajo.",a:"Plat\xF3n"},{t:"No hay mal que dure cien a\xF1os ni cuerpo que lo resista: todo pasa.",a:"Dicho popular"},{t:"La mejor hora para plantar un \xE1rbol fue hace veinte a\xF1os; la segunda mejor hora es ahora.",a:"Proverbio chino"},{t:"Los dos d\xEDas m\xE1s importantes de tu vida son el d\xEDa que naces y el d\xEDa en que descubres por qu\xE9.",a:"Mark Twain"},{t:"Donde no hay amor, pon amor, y encontrar\xE1s amor.",a:"San Juan de la Cruz"},{t:"Parece siempre imposible hasta que se hace.",a:"Nelson Mandela"},{t:"Cada atardecer es prueba de que terminar tambi\xE9n puede ser hermoso.",a:"An\xF3nimo"},{t:"Nuestro mayor defecto est\xE1 en rendirnos; el modo m\xE1s seguro de salir adelante es intentarlo una vez m\xE1s.",a:"Thomas Edison"},{t:"Si quieres ser feliz, s\xE9lo.",a:"Le\xF3n Tolst\xF3i"},{t:"Se aprende a vivir aprendiendo a dar.",a:"Mario Benedetti"},{t:"No cuentes los d\xEDas: haz que los d\xEDas cuenten.",a:"An\xF3nimo"},{t:"\xBFCu\xE1ntos de nosotros estar\xEDamos contentos de haber vivido como Anne Frank, escribiendo luz desde el s\xF3tano?",a:"An\xF3nimo"},{t:"Los que entregan su libertad a cambio de seguridad no merecen ni libertad ni seguridad.",a:"Benjamin Franklin"},{t:"Y fue por ese r\xEDo que lleg\xF3 a mi vida el ruido del mar.",a:"Pablo Neruda"},{t:"El r\xEDo no bebe su propia agua; el \xE1rbol no come su propia fruta: vivimos d\xE1ndonos unos a otros.",a:"Proverbio africano"},{t:"Caminante, no hay camino: se hace camino al andar.",a:"Antonio Machado"},{t:"Sube conmigo, amor americano.",a:"Pablo Neruda"},{t:"Anoche perd\xED el mundo y gan\xE9 el universo.",a:"Rumi"},{t:"La nieve cubre los campos, pero no esconde el camino del que sabe leer las estrellas.",a:"Proverbio n\xF3rdico"},{t:"Elige un trabajo que ames y no tendr\xE1s que trabajar ni un d\xEDa en tu vida.",a:"Confucio"},{t:"Vencerse a s\xED mismo es victoria mayor que vencer mil veces a mil hombres.",a:"Buda"},{t:"Una flor no compite con la flor vecina; simplemente florece.",a:"Proverbio japon\xE9s"},{t:"La medida \xFAltima de una persona no es d\xF3nde se para en los momentos de comodidad, sino d\xF3nde se para en los desaf\xEDos.",a:"Martin Luther King"},{t:"Cada uno de mis libros me ha ense\xF1ado algo nuevo, y sobre todo, me ha ense\xF1ado lo que yo ignoraba.",a:"Julio Cort\xE1zar"},{t:"Todo lo que hagas, hazlo con todo tu coraz\xF3n, o no lo hagas en absoluto.",a:"Confucio"},{t:"Los recuerdos son del coraz\xF3n; las palabras, solo del papel.",a:"Gabriel Garc\xEDa M\xE1rquez"},{t:"El viento contrario tambi\xE9n sostiene al ave que sabe inclinarse.",a:"An\xF3nimo"},{t:"La belleza salvar\xE1 al mundo si aprendemos a reconocerla en lo cotidiano.",a:"Fi\xF3dor Dostoyevski"},{t:"Primero decide qui\xE9n quieres ser; despu\xE9s, haz lo que debas hacer.",a:"Epicteto"},{t:"Vivir es lo m\xE1s raro del mundo; la mayor\xEDa de la gente apenas existe.",a:"Oscar Wilde"},{t:"S\xE9 curioso sobre ellos, no sobre sus juicios; mantente siempre con la cara alegre hacia la luz.",a:"Walt Whitman"},{t:"Para ser irremplazable, uno debe ser siempre diferente.",a:"Coco Chanel"},{t:"Un hombre se convierte en lo que sue\xF1a cuando hace de su camino su casa.",a:"Antoine de Saint-Exup\xE9ry"},{t:"Todo cambia, y lo que hoy parece final es apenas un giro del camino.",a:"Mercedes Sosa"},{t:"Andar es la mejor manera de conversar con el mundo.",a:"Julio Cort\xE1zar"},{t:"Cuando manejas a trescientos kil\xF3metros por hora, la lluvia parece s\xF3lida; as\xED son los sue\xF1os cuando los persigues a fondo.",a:"Ayrton Senna"},{t:"La diligencia es madre de la buena ventura.",a:"Miguel de Cervantes"},{t:"Mejor hazlo imperfecto hoy que perfecto jam\xE1s.",a:"Winston Churchill"},{t:"Haz tu trabajo y luego da un paso atr\xE1s: es el \xFAnico camino a la serenidad.",a:"Lao Ts\xE9"},{t:"El alma se ti\xF1e del color de sus pensamientos.",a:"Marco Aurelio"},{t:"Ser o no ser: esa es la pregunta. Decidir es el primer acto de libertad.",a:"William Shakespeare"},{t:"Lo que se opone al camino se convierte en el camino.",a:"Marco Aurelio"},{t:"Lo que demuestras hoy con calma ser\xE1 cre\xEDdo ma\xF1ana por todos.",a:"Henry David Thoreau"},{t:"El miedo avisa; el valor decide; la acci\xF3n transforma.",a:"An\xF3nimo"},{t:"S\xE9 paciente contigo: nada bueno crece apresurado, ni el trigo ni el alma.",a:"An\xF3nimo"},{t:"Todas las ambiciones humanas son hermosas cuando llevan semillas de nobleza.",a:"Alexandre Dumas"},{t:"Al mar no se le pregunta ad\xF3nde va: se aprende a navegar con \xE9l.",a:"Dicho popular"},{t:"La riqueza no consiste en tener mucho, sino en desear poco.",a:"Epicteto"},{t:"Es imposible aprender aquello que uno cree que ya sabe.",a:"Epicteto"},{t:"Hoy vence a ti mismo de ayer; ma\xF1ana vence al m\xE1s fuerte.",a:"Miyamoto Musashi"},{t:"El que persevera alcanza; el que insiste aprende dos veces.",a:"Dicho popular"},{t:"No compares tu cap\xEDtulo uno con el cap\xEDtulo veinte de otro.",a:"An\xF3nimo"},{t:"Genio: uno por ciento inspiraci\xF3n y noventa y nueve por ciento transpiraci\xF3n.",a:"Thomas Edison"},{t:"El secreto de una buena vejez es un pacto honesto con la soledad y una pasi\xF3n que no envejece.",a:"Gabriel Garc\xEDa M\xE1rquez"},{t:"Recuerda que no obtener lo que quieres es a veces un golpe de suerte maravilloso.",a:"Dalai Lama"},{t:"El que da a los pobres no se empobrece; siembra en terreno que nunca falla.",a:"Proverbio \xE1rabe"},{t:"No esperes a sentirte listo: la preparaci\xF3n ocurre mientras caminas.",a:"An\xF3nimo"},{t:"Incluso la noche m\xE1s oscura terminar\xE1 y el sol saldr\xE1 de nuevo.",a:"Victor Hugo"},{t:"Lo que no te mata te hace m\xE1s fuerte.",a:"Friedrich Nietzsche"},{t:"El secreto del cambio es concentrar toda tu energ\xEDa no en luchar contra lo viejo, sino en construir lo nuevo.",a:"S\xF3crates"},{t:"No le temas al hombre que practica diez mil golpes distintos; teme al que practica un golpe diez mil veces.",a:"Bruce Lee"},{t:"La compasi\xF3n y la tolerancia no son signos de debilidad, sino de fuerza.",a:"Dalai Lama"},{t:"Nadie necesita esperar ni un momento para empezar a mejorar el mundo: es maravilloso cu\xE1nto puede hacerse.",a:"Anne Frank"},{t:"Un hombre con una idea nueva es un loco hasta que la idea triunfa.",a:"Mark Twain"},{t:"Tu tiempo es limitado, as\xED que no lo gastes viviendo la vida de otro.",a:"Steve Jobs"},{t:"Nada est\xE1 perdido si se tiene el valor de proclamar que todo est\xE1 perdido y hay que empezar de nuevo.",a:"Julio Cort\xE1zar"},{t:"Puedo escribir los versos m\xE1s tristes esta noche. Escribir, por ejemplo: la noche est\xE1 estrellada.",a:"Pablo Neruda"},{t:"Quien arregla su propia vela ilumina tambi\xE9n el bote vecino.",a:"An\xF3nimo"},{t:"Quien conoce a los dem\xE1s es sabio; quien se conoce a s\xED mismo est\xE1 despierto.",a:"Lao Ts\xE9"},{t:"Ayer era listo y quer\xEDa cambiar el mundo; hoy soy sabio y me cambio yo.",a:"Rumi"},{t:"No es pobre el que tiene poco, sino el que desea m\xE1s.",a:"S\xE9neca"},{t:"La esperanza es el sue\xF1o del hombre despierto.",a:"Arist\xF3teles"},{t:"El que espera el momento perfecto pierde todos los momentos buenos.",a:"An\xF3nimo"},{t:"Ven, ven, quienquiera que seas; a\xFAn as\xED ven: el nuestro no es una caravana de desesperaci\xF3n.",a:"Rumi"},{t:"El agua es lo m\xE1s blando de todas las cosas, pero vence a lo m\xE1s duro.",a:"Lao Ts\xE9"},{t:"M\xE1s vale p\xE1jaro en mano que aprender a construir nidos: primero asegura, despu\xE9s sue\xF1a.",a:"Dicho popular"},{t:"Lo que puedes hacer o sue\xF1as poder hacer, empiezalo; la osad\xEDa lleva en s\xED misma genio y poder.",a:"Johann Wolfgang von Goethe"},{t:"Una marea alta comienza siempre bajo el nivel de todas las mareas bajas.",a:"An\xF3nimo"},{t:"Lo dif\xEDcil se hace en alg\xFAn momento; lo imposible, un poco m\xE1s tarde.",a:"An\xF3nimo"},{t:"No juzgues a tu hermano hasta que hayas caminado una luna entera con sus pasos.",a:"Proverbio cherokee"},{t:"El ganado muere, la familia muere; solo la fama de las buenas obras nunca muere.",a:"H\xE1vam\xE1l n\xF3rdico"},{t:"Primero piensa, segundo cree, tercero sue\xF1a, y finalmente atr\xE9vete.",a:"Walt Disney"},{t:"Yo me celebro y me canto a m\xED mismo; y todo lo que soy tambi\xE9n lo eres t\xFA.",a:"Walt Whitman"},{t:"Hay cosas m\xE1s valiosas que la valent\xEDa: hay cosas que solo se aprenden perdonando.",a:"C. S. Lewis"},{t:"La verdadera generosidad hacia el futuro consiste en dar todo al presente.",a:"Albert Camus"},{t:"El guerrero que espera el momento perfecto nunca pelea.",a:"An\xF3nimo"},{t:"Si vas atravesando el infierno, sigue avanzando.",a:"Winston Churchill"},{t:"El que pregunta es tonto cinco minutos; el que no pregunta, lo es toda la vida.",a:"Proverbio chino"},{t:"Nunca mires hacia abajo para comenzar una escalera; mira hacia arriba y sube.",a:"Henry David Thoreau"},{t:"El que quiere miel debe soportar las picaduras de las abejas.",a:"Proverbio \xE1rabe"},{t:"Cada d\xEDa es una p\xE1gina nueva: escribe algo que valga ser rele\xEDdo.",a:"An\xF3nimo"},{t:"Yo hice a mis hijos pobres para que mis hijos no fueran pobres de coraz\xF3n. Los hice sencillos para ser grandes.",a:"Gabriela Mistral"},{t:"Cada persona, cuando abre los ojos por la ma\xF1ana, recibe una p\xE1gina nueva del mundo.",a:"Eduardo Galeano"},{t:"Sin esfuerzo no hay pez que salte a la orilla.",a:"Proverbio ruso"},{t:"El amor ha de saber esperar; casi siempre la prisa lo arruina todo.",a:"Gabriela Mistral"},{t:"Comienza de inmediato a vivir y cuenta cada d\xEDa como una vida separada.",a:"S\xE9neca"},{t:"Toda tu vida has estado esperando a ti mismo; no huyas m\xE1s.",a:"Yalal ad-Din Rumi"},{t:"Sost\xE9n en tus manos solo esto: el momento presente.",a:"Buda"},{t:"Si quieres saber ad\xF3nde vas, pregunta a quien ya volvi\xF3 del camino.",a:"Proverbio africano"},{t:"Dime y lo olvido; ens\xE9\xF1ame y quiz\xE1 recuerde; invol\xFAcrame y aprender\xE9.",a:"Benjamin Franklin"},{t:"Camar\xF3n que se duerme se lo lleva la corriente: mantente despierto ante tus sue\xF1os.",a:"Dicho popular"},{t:"Una puerta que no abrimos tambi\xE9n es una respuesta; atrevete a girar la manilla.",a:"Franz Kafka"},{t:"El maestro muestra la puerta, pero debes ser t\xFA quien la cruce.",a:"Proverbio chino"},{t:"Caer es permitido; levantarse es obligatorio. Y mientras haya vida, hay oportunidad.",a:"Nelson Mandela"},{t:"No te rindas, a\xFAn est\xE1s a tiempo de alcanzar y comenzar de nuevo.",a:"Mario Benedetti"},{t:"Cae siete veces, lev\xE1ntate ocho.",a:"Proverbio japon\xE9s"},{t:"Escribe en tu coraz\xF3n que cada d\xEDa es el mejor d\xEDa del a\xF1o.",a:"Ralph Waldo Emerson"},{t:"Ya sea que creas poder hacerlo o que creas que no puedes, en ambos casos tienes raz\xF3n.",a:"Henry Ford"},{t:"El que no tiene valor para so\xF1ar despierto nunca ver\xE1 cumplirse sus sue\xF1os dormido.",a:"Muhammad Ali"},{t:"La duda es uno de los nombres de la inteligencia.",a:"Jorge Luis Borges"},{t:"Quien tiene un porqu\xE9 para vivir puede soportar casi cualquier c\xF3mo.",a:"Friedrich Nietzsche"},{t:"El mayor placer de la vida es hacer lo que la gente dice que no puedes.",a:"Alexandre Dumas"},{t:"Un viaje de mil leguas comienza siempre con un primer paso.",a:"Lao Ts\xE9"},{t:"Al que madruga, la vida lo despierta con m\xE1s horas de luz.",a:"Dicho popular chileno"},{t:"El invierno siempre encuentra en s\xED mismo una promesa secreta de primavera.",a:"Proverbio n\xF3rdico"},{t:"Una vida sin examen no merece ser vivida.",a:"S\xF3crates"},{t:"Aunque el mundo est\xE9 lleno de sufrimiento, tambi\xE9n est\xE1 lleno de la superaci\xF3n del sufrimiento.",a:"Helen Keller"},{t:"Solo los educados son libres.",a:"Epicteto"},{t:"El poeta es un peque\xF1o dios que crea mundos con palabras aladas.",a:"Vicente Huidobro"},{t:"Canta lo que sientes y el mundo encontrar\xE1 en tu voz lo que \xE9l mismo siente.",a:"Atahualpa Yupanqui"},{t:"Ten siempre contigo un sue\xF1o imposible: mantiene viva la parte de ti que a\xFAn puede creer.",a:"Oscar Wilde"},{t:"Escucha el murmullo del agua y aprender\xE1s que la fuerza puede ser suave.",a:"Proverbio nativo americano"},{t:"Cada vez que te ense\xF1a algo, el mundo se vuelve un poco menos desconocido.",a:"Lewis Carroll"},{t:"Si buscas tranquilidad, haz menos cosas, pero hazlas mejor.",a:"Marco Aurelio"},{t:"No tenemos dos vidas: una para aprender y otra para aplicar lo aprendido. Solo hay una.",a:"S\xE9neca"},{t:"Ve hasta donde puedas; cuando llegues all\xED, ver\xE1s m\xE1s lejos.",a:"Thomas Carlyle"},{t:"La espada gana batallas; el car\xE1cter gana vidas.",a:"Proverbio japon\xE9s"},{t:"Empieza donde est\xE1s, con lo que tienes, y el camino aparecer\xE1 bajo tus pasos.",a:"An\xF3nimo"},{t:"En pleno invierno descubr\xED en m\xED un invencible verano.",a:"Albert Camus"},{t:"El \xE9xito no es cuesti\xF3n de talento sino de pasi\xF3n y constancia.",a:"Pel\xE9"},{t:"Todo lo que tenemos que decidir es qu\xE9 hacer con el tiempo que se nos ha dado.",a:"J. R. R. Tolkien"},{t:"S\xE9 t\xFA mismo; los dem\xE1s puestos ya est\xE1n tomados.",a:"Oscar Wilde"},{t:"S\xE9 agua, amigo m\xEDo: vac\xEDa tu mente, s\xE9 informe, sin forma, como el agua.",a:"Bruce Lee"},{t:"La vida es breve; el arte, largo; la oportunidad, fugaz; la experiencia, enga\xF1osa; el juicio, dif\xEDcil.",a:"Horacio"},{t:"La mejor manera de animarte a ti mismo es intentar animar a alguien m\xE1s.",a:"Mark Twain"},{t:"Guarda tu naturaleza salvaje: ella es tu ra\xEDz m\xE1s honda y tu mejor br\xFAjula.",a:"Walt Whitman"},{t:"No hay nada m\xE1s fuerte que quienes convierten su herida en luz para otros.",a:"Fi\xF3dor Dostoyevski"},{t:"Pies, \xBFpara qu\xE9 los quiero si tengo alas para volar?",a:"Frida Kahlo"},{t:"Aprende de las reglas como un experto, pero v\xEDvelas como un artista.",a:"Dalai Lama"},{t:"La memoria es del coraz\xF3n, y el olvido tambi\xE9n; pero la esperanza es del pueblo entero.",a:"Eduardo Galeano"},{t:"Muy poco se necesita para una vida feliz; todo est\xE1 dentro de ti, en tu manera de pensar.",a:"Marco Aurelio"},{t:"La sabidur\xEDa est\xE1 en el asombro; quien deja de asombrarse, envejece.",a:"Octavio Paz"},{t:"No todo lo que es oro brilla, ni todos los que vagan est\xE1n perdidos.",a:"J. R. R. Tolkien"},{t:"El sol calienta a todos por igual, pero nadie quema su casa para asar su pan.",a:"Proverbio \xE1rabe"},{t:"Un gramo de acci\xF3n vale m\xE1s que una tonelada de intenciones.",a:"Benjamin Franklin"},{t:"Una pasi\xF3n compartida multiplica la fuerza de quien la sostiene.",a:"Antonio Sk\xE1rmeta"},{t:"No temas a la grandeza: algunos nacen grandes, otros la alcanzan y otros la buscan cada d\xEDa.",a:"William Shakespeare"},{t:"El visionario susurra ideas al viento; el sabio las planta en tierra firme.",a:"Proverbio japon\xE9s"},{t:"El futuro pertenece a quienes creen en la belleza de sus sue\xF1os.",a:"Eleanor Roosevelt"},{t:"La \xFAnica manera de hacer un gran trabajo es amar lo que haces; si a\xFAn no lo encontraste, sigue buscando.",a:"Steve Jobs"},{t:"Que tu camino siga al sol naciente hasta que el cansancio te encuentre sonriendo.",a:"Bendici\xF3n irlandesa"},{t:"Flota como mariposa, pica como abeja: cada golpe debe tener prop\xF3sito detr\xE1s.",a:"Muhammad Ali"},{t:"La \xFAnica manera de tener un amigo es siendo uno.",a:"Ralph Waldo Emerson"},{t:"Aprende a descansar, no a rendirte.",a:"An\xF3nimo"},{t:"Donde pongas tu atenci\xF3n, ah\xED pondr\xE1s tambi\xE9n tu vida.",a:"An\xF3nimo"},{t:"Cree en ti mismo y ya vas por la mitad del camino.",a:"Theodore Roosevelt"},{t:"No importa lo que hayas hecho; lo importante es hacia d\xF3nde vas ahora.",a:"Martin Luther King"},{t:"Cuida tus pensamientos porque se har\xE1n palabras; cuida tus palabras porque se har\xE1n actos.",a:"Lao Ts\xE9"},{t:"Lo que la mano hace en secreto, el alma lo sabe a gritos.",a:"Gabriela Mistral"},{t:"La disciplina elegida se siente como libertad; la impuesta, como cadena.",a:"An\xF3nimo"},{t:"En las desdichas se conoce al amigo verdadero.",a:"Francisco de Quevedo"},{t:"Cuando bebas agua recuerda qui\xE9n trajo la lluvia; gratitud es memoria del coraz\xF3n.",a:"Proverbio nativo americano"},{t:"Lo esencial es invisible a los ojos; mira con el coraz\xF3n.",a:"Antoine de Saint-Exup\xE9ry"},{t:"Todos tus sue\xF1os pueden hacerse realidad si tienes el coraje de perseguirlos.",a:"Walt Disney"},{t:"No hay dolor que dure, ni pena que no se cure cantando.",a:"Violeta Parra"},{t:"Sabio es quien conoce los medios necesarios en cada caso.",a:"Johann Wolfgang von Goethe"},{t:"Somos hechos de la misma materia que los sue\xF1os.",a:"William Shakespeare"},{t:"Si cada uno barre delante de su puerta, todo el pueblo estar\xE1 limpio.",a:"Proverbio alem\xE1n"},{t:"No es porque las cosas sean dif\xEDciles que no nos atrevemos; es porque no nos atrevemos que son dif\xEDciles.",a:"S\xE9neca"},{t:"Nunca dejes que la escuela interfiera con tu educaci\xF3n.",a:"Mark Twain"},{t:"Somos vecinos de nuestros sue\xF1os cuando trabajamos junto a ellos.",a:"An\xF3nimo"},{t:"La vida sin fiesta es un largo camino sin fuentes.",a:"Proverbio griego"},{t:"La vida es como andar en bicicleta: para mantener el equilibrio, debes seguir movi\xE9ndote.",a:"Albert Einstein"},{t:"La manera de empezar es dejar de hablar y comenzar a hacer.",a:"Walt Disney"},{t:"La constancia convierte lo extraordinario en rutina posible.",a:"An\xF3nimo"},{t:"Debes subir la monta\xF1a sabiendo que la cima te har\xE1 ver otras monta\xF1as.",a:"Proverbio chino"},{t:"Tu \xFAnico l\xEDmite real es el que aceptas sin discutir.",a:"An\xF3nimo"},{t:"La fuerza no viene de la capacidad f\xEDsica, sino de una voluntad indomable.",a:"Mahatma Gandhi"},{t:"Amor es la palabra m\xE1s malgastada y la m\xE1s necesitada para hacer valer la vida.",a:"Octavio Paz"},{t:"No son las cosas las que perturban a las personas, sino sus opiniones sobre ellas.",a:"Epicteto"},{t:"Yo no soy el m\xE1s apto, pero me quedo m\xE1s tiempo martillando la misma piedra.",a:"Abraham Lincoln"},{t:"El \xE9xito no es final; el fracaso no es fatal: lo que cuenta es el coraje de continuar.",a:"Winston Churchill"},{t:"Locura es hacer siempre lo mismo y esperar resultados distintos.",a:"Albert Einstein"},{t:"La paz empieza con una sonrisa.",a:"Madre Teresa"},{t:"Todo lo que somos es resultado de lo que hemos pensado.",a:"Buda"},{t:"El hombre que tiene un porqu\xE9 vive con paciencia cualquier destino.",a:"Fi\xF3dor Dostoyevski"},{t:"La oscuridad no puede expulsar a la oscuridad; solo la luz puede hacerlo.",a:"Martin Luther King"},{t:"Mantente hambriento; mantente necio; mantente despierto ante tu propia vida.",a:"Steve Jobs"},{t:"El secreto de salir adelante es comenzar.",a:"Mark Twain"},{t:"Sonr\xEDe: es el idioma m\xE1s corto entre dos desconocidos.",a:"An\xF3nimo"},{t:"Los primeros en disculparse son los m\xE1s valientes.",a:"Plat\xF3n"},{t:"Lo bueno, si breve, dos veces bueno.",a:"Baltasar Graci\xE1n"},{t:"La paz viene de dentro; no la busques fuera.",a:"Buda"},{t:"Un d\xEDa sin intentar nada nuevo es un d\xEDa que el calendario guarda en gris.",a:"An\xF3nimo"},{t:"Sola podemos hacer tan poco; juntas podemos hacer tanto.",a:"Helen Keller"},{t:"No hay pasi\xF3n por encontrar en una vida f\xE1cil; la gloria nace de vencer lo dif\xEDcil.",a:"Nelson Mandela"},{t:"Dame seis horas para cortar un \xE1rbol y pasar\xE9 las primeras cuatro afilando el hacha.",a:"Abraham Lincoln"},{t:"El optimismo ingenuo espera que todo salga bien sin motivo; la esperanza trabaja para que salga bien.",a:"Winston Churchill"},{t:"Todo tiene su tiempo, y todo lo que se quiere debajo del cielo tiene su hora.",a:"Eclesiast\xE9s"},{t:"Lo mejor del futuro es que llega un d\xEDa a la vez.",a:"Abraham Lincoln"},{t:"Que tus hijos sean como flechas vivas lanzadas hacia un ma\xF1ana luminoso.",a:"Jalil Gibran"},{t:"Despacio respiro, despacio camino; pero siempre adelante.",a:"Mario Benedetti"},{t:"Hoy es el alumno de ayer; ma\xF1ana ser\xE1 maestro de alguien.",a:"Proverbio japon\xE9s"},{t:"Un buen amigo vale m\xE1s que cien parientes lejanos.",a:"Proverbio irland\xE9s"},{t:"La inspiraci\xF3n llega cuando menos la buscas, pero solo visita a quien trabaja.",a:"Gustavo Adolfo B\xE9cquer"},{t:"Ni siquiera el m\xE1s sabio puede ver todos los caminos que se abren ante tus pies.",a:"J. R. R. Tolkien"},{t:"Odio cada minuto de entrenamiento, pero me dije: no renuncies; sufre ahora y vive el resto de tu vida como campe\xF3n.",a:"Muhammad Ali"},{t:"Somos lo que hacemos repetidamente; la excelencia, entonces, no es un acto, sino un h\xE1bito.",a:"Arist\xF3teles"},{t:"La sabidur\xEDa nos llega cuando ya no nos sirve de nada.",a:"Gabriel Garc\xEDa M\xE1rquez"},{t:"Con paciencia se cruza el oc\xE9ano paso a paso.",a:"Proverbio griego"},{t:"Mientras posponemos la vida, esta pasa.",a:"S\xE9neca"},{t:"A quienes les parec\xEDa que bail\xE1bamos locos, era porque no pod\xEDan escuchar la m\xFAsica.",a:"Friedrich Nietzsche"},{t:"El ojo del amo engorda al caballo: cuida lo tuyo y crecer\xE1.",a:"Proverbio ruso"},{t:"En medio del invierno aprend\xED por fin que hab\xEDa en m\xED un sol inagotable.",a:"Albert Camus"},{t:"Un poco de fragancia siempre queda en las manos de quien da flores.",a:"Jalil Gibran"},{t:"Las gotas de agua tallan la piedra no por fuerza, sino por caer con frecuencia.",a:"Ovidio"},{t:"Escribe tu vida con la tinta del coraje; los cap\xEDtulos tristes tambi\xE9n hacen grandes historias.",a:"Isabel Allende"},{t:"Todo experto fue alguna vez un principiante que no se rindi\xF3.",a:"An\xF3nimo"},{t:"Cuanto m\xE1s te celebras por lo que no tienes, menos disfrutas lo que s\xED tienes.",a:"Oprah Winfrey"},{t:"Tienes poder sobre tu mente, no sobre los acontecimientos externos. Comprende esto y hallar\xE1s fuerza.",a:"Marco Aurelio"},{t:"Lo importante es que nunca te acostumbres a la injusticia: la costumbre es la primera muerte del alma.",a:"Antonio Sk\xE1rmeta"},{t:"Nadie puede hacerte sentir inferior sin tu consentimiento.",a:"Eleanor Roosevelt"},{t:"Peque\xF1os pasos diarios valen m\xE1s que grandes saltos ocasionales.",a:"An\xF3nimo"},{t:"La felicidad es amor; nada m\xE1s. Es feliz quien ama, quien trabaja y quien comparte.",a:"Hermann Hesse"},{t:"Tu tarea no es buscar el amor, sino encontrar las barreras que t\xFA mismo construiste contra \xE9l.",a:"Yalal ad-Din Rumi"},{t:"Hay solo dos d\xEDas en el a\xF1o en que nada se puede hacer: uno se llama ayer y otro ma\xF1ana.",a:"Dalai Lama"},{t:"Los mejores y m\xE1s hermosos cosas del mundo no pueden verse ni tocarse: deben sentirse con el coraz\xF3n.",a:"Helen Keller"},{t:"Querer es poder cuando el querer camina.",a:"Proverbio latino"},{t:"Las estrellas no se apagan por la noche; solo esperan ojos que busquen.",a:"An\xF3nimo"},{t:"Ser segundo es ser el primero de los perdedores; pero perder ense\xF1ando es ganar para siempre.",a:"Ayrton Senna"},{t:"Despacio se va lejos cuando la direcci\xF3n es buena.",a:"Proverbio ruso"},{t:"La revoluci\xF3n comienza siempre con una palabra dicha a tiempo y con amor.",a:"Ernesto Cardenal"},{t:"Arriba con el rostro lavado de aurora quien luch\xF3 por la alegr\xEDa.",a:"Pablo Neruda"},{t:"La sabidur\xEDa de la vida consiste en eliminar lo que no importa.",a:"Ant\xF3n Ch\xE9jov"},{t:"No hay escuela igual a la casa, ni maestro como la madre.",a:"Gabriela Mistral"},{t:"Hoy todav\xEDa tiene espacio para convertirse en tu d\xEDa favorito.",a:"An\xF3nimo"},{t:"A donde el coraz\xF3n va, el pie llega aunque tarde.",a:"Dicho popular"},{t:"La vida solo puede ser comprendida mirando hacia atr\xE1s, pero debe ser vivida mirando hacia adelante.",a:"S\xF8ren Kierkegaard"},{t:"Seamos realistas: exijamos lo imposible. La imaginaci\xF3n al poder.",a:"Frida Kahlo"},{t:"El precio de cualquier cosa es la cantidad de vida que cambias por ella.",a:"Henry David Thoreau"},{t:"Un viaje de mil leguas tambi\xE9n se recorre paso a paso: el sabio no se apresura, avanza.",a:"Proverbio chino"},{t:"No busques luz afuera cuando puedes encender una dentro.",a:"An\xF3nimo"},{t:"S\xE9 el cambio que quieres ver en el mundo.",a:"Mahatma Gandhi"},{t:"Todos felices los que creen; m\xE1s felices los que construyen lo que creen.",a:"Le\xF3n Tolst\xF3i"},{t:"La educaci\xF3n es el arma m\xE1s poderosa que puedes usar para cambiar el mundo.",a:"Nelson Mandela"},{t:"La paciencia es el \xE1rbol de ra\xEDz amarga pero de frutos muy dulces.",a:"Proverbio persa"},{t:"Vive como si fueras a morir ma\xF1ana; aprende como si fueras a vivir siempre.",a:"Mahatma Gandhi"},{t:"Primero te ignoran, luego se r\xEDen, luego pelean; entonces ganas.",a:"Mahatma Gandhi"},{t:"Hay que correr tan r\xE1pido como puedas para quedarse en el mismo lugar; para llegar a otra parte hay que correr el doble.",a:"Lewis Carroll"},{t:"Yo solo s\xE9 que no s\xE9 nada.",a:"S\xF3crates"},{t:"La paz interior comienza el momento en que decides no dejar que otra persona o evento controle tus emociones.",a:"Dalai Lama"},{t:"Mientras respiro, espero.",a:"Proverbio latino"},{t:"Ning\xFAn r\xEDo regresa a su fuente, pero todos encuentran el mar.",a:"Proverbio japon\xE9s"},{t:"Est\xE1 prohibido rendirse, prohibido perder la fe, prohibido caminar sin alegr\xEDa.",a:"Eduardo Galeano"},{t:"La suerte es lo que sucede cuando la preparaci\xF3n encuentra la oportunidad.",a:"S\xE9neca"},{t:"Empieza peque\xF1o, empieza torpe, pero empieza hoy.",a:"An\xF3nimo"},{t:"Cuando el viento sopla fuerte, los \xE1rboles d\xE9biles aprenden a bailar.",a:"Dicho popular"},{t:"La simplicidad es la m\xE1xima elegancia; quita todo lo innecesario y quedar\xE1 lo esencial.",a:"Coco Chanel"},{t:"No hay nada fuera de ti mismo que pueda darte poder.",a:"Miyamoto Musashi"},{t:"Deja que tus logros hablen despacio y largo tiempo.",a:"An\xF3nimo"},{t:"Los que dicen que algo no se puede hacer no deber\xEDan interrumpir a los que lo est\xE1n haciendo.",a:"Proverbio chino"},{t:"Las olas no preguntan cu\xE1ntas veces rompieron contra la roca: siguen llegando.",a:"An\xF3nimo"},{t:"Si piensas que algo es imposible, lo har\xE1s imposible; si crees posible, ya empezaste.",a:"Bruce Lee"},{t:"Cualquier destino, por largo y complicado que sea, es en realidad una sola instant\xE1nea: el instante en que el hombre descubre qui\xE9n es.",a:"Jorge Luis Borges"},{t:"Conoce a tu enemigo y con\xF3cete a ti mismo; en cien batallas no correr\xE1s peligro.",a:"Sun Tzu"},{t:"La marea que hoy parece contra ti es la misma agua que ma\xF1ana te llevar\xE1 a mar abierto.",a:"An\xF3nimo"},{t:"Las palabras son como el viento; los hechos son como la monta\xF1a.",a:"Proverbio chino"},{t:"No vayas donde pueda llevarte un sendero; ve donde no haya ninguno y deja huella.",a:"Ralph Waldo Emerson"},{t:"Muchas manos peque\xF1as, trabajando juntas, mueven monta\xF1as enteras.",a:"Proverbio africano"},{t:"Todos piensan en cambiar el mundo, pero nadie piensa en cambiarse a s\xED mismo.",a:"Le\xF3n Tolst\xF3i"},{t:"Lo que la sangre calla, la voz lo canta; y cantar ya es empezar a sanar.",a:"Jaime Sabines"},{t:"Escribe las heridas en la arena y los favores en la piedra.",a:"Proverbio \xE1rabe"},{t:"Ve confiado en la direcci\xF3n de tus sue\xF1os; vive la vida que imaginas.",a:"Henry David Thoreau"},{t:"El trabajo es amor hecho visible.",a:"Jalil Gibran"},{t:"Yo no he fracasado; simplemente encontr\xE9 diez mil maneras que no funcionan.",a:"Thomas Edison"},{t:"Deja que las cosas fluyan como el agua: la fuerza no est\xE1 en la rigidez sino en adaptarse sin romperse.",a:"Bruce Lee"},{t:"Mientras haya un coraz\xF3n que sienta, habr\xE1 poes\xEDa que lo despierte.",a:"Gustavo Adolfo B\xE9cquer"},{t:"Nuestra mayor gloria no es caer nunca, sino levantarnos cada vez que caemos.",a:"Confucio"},{t:"Lo que buscas te est\xE1 buscando tambi\xE9n.",a:"Rumi"},{t:"Todo lo que una persona imagina, otra puede hacerlo realidad.",a:"Julio Verne"},{t:"S\xE9 fiel a ti mismo y no podr\xE1s enga\xF1ar a nadie.",a:"An\xF3nimo"},{t:"No hay nada escrito para nadie; el futuro es un territorio que se construye caminando.",a:"Gabriel Garc\xEDa M\xE1rquez"},{t:"El silencio del amanecer guarda respuestas que el ruido del d\xEDa desordena.",a:"An\xF3nimo"},{t:"La fortuna favorece a los audaces.",a:"Virgilio"},{t:"La felicidad no es una meta, sino un m\xE9todo de viaje.",a:"Mario Benedetti"},{t:"Ser bueno es f\xE1cil; ser justo, eso s\xED es dif\xEDcil.",a:"Victor Hugo"},{t:"Nada te turbe, nada te espante; todo se pasa, quien a Dios espera no le falta nada.",a:"Santa Teresa de Jes\xFAs"},{t:"No digas que eres incapaz: di todav\xEDa no puedo, y practica.",a:"Ant\xF3n Ch\xE9jov"},{t:"Las palabras no est\xE1n hechas para esconder los pensamientos, sino para mostrarlos.",a:"Nicanor Parra"},{t:"Un buen comienzo es la mitad del trabajo entero.",a:"Proverbio griego"},{t:"A\xFAn hay esperanza mientras los corazones fieles laten juntos.",a:"J. R. R. Tolkien"},{t:"Los pueblos unidos jam\xE1s ser\xE1n vencidos cuando su canto se levanta con dignidad.",a:"V\xEDctor Jara"},{t:"No hay nada m\xE1s hermoso que tener un sue\xF1o claro y la fuerza para perseguirlo.",a:"Frida Kahlo"},{t:"Vive de modo que tu presencia sume y tu ausencia duela poco.",a:"An\xF3nimo"},{t:"Cuando bebas agua, recuerda la primavera.",a:"Proverbio sioux"},{t:"Tengo un sue\xF1o, y cada d\xEDa que trabajo por \xE9l lo hago un poco m\xE1s real.",a:"Martin Luther King"},{t:"Gota a gota, el agua talla no solo la piedra sino tambi\xE9n el car\xE1cter.",a:"Proverbio latino"},{t:"Educar la mente sin educar el coraz\xF3n no es educaci\xF3n en absoluto.",a:"Arist\xF3teles"},{t:"El camino se construye andando, aunque empiece bajo tus propios pies dudosos.",a:"Franz Kafka"},{t:"El valiente no es quien no siente miedo, sino quien lo conquista.",a:"Nelson Mandela"},{t:"Piensa en toda la belleza que a\xFAn queda alrededor tuyo y al\xE9grate.",a:"Anne Frank"},{t:"Gracias a la vida que me ha dado tanto: me dio la risa y me dio el llanto.",a:"Violeta Parra"},{t:"Para volar, no busques alas prestadas: cultiva tu propio viento.",a:"Antoine de Saint-Exup\xE9ry"},{t:"El que mueve una monta\xF1a comienza cargando piedras peque\xF1as.",a:"Confucio"},{t:"Entre el sue\xF1o y la acci\xF3n hay puentes llamados decisiones.",a:"Khalil Gibran"},{t:"La cultura no pertenece solo a los que tienen dinero; pertenece a todos.",a:"V\xEDctor Jara"},{t:"Innovaci\xF3n distingue a un l\xEDder de un seguidor.",a:"Steve Jobs"},{t:"La duda hace vacilar a los cobardes y despierta a los valientes.",a:"William Shakespeare"},{t:"Todo pensamiento verdadero se realiza alguna d\xEDa.",a:"Le\xF3n Tolst\xF3i"},{t:"Cuando est\xE9s sediento, cava tu propio pozo: el agua ajena nunca sabe igual.",a:"Proverbio japon\xE9s"},{t:"Yo te cuento este sue\xF1o para que t\xFA lo contin\xFAes.",a:"Jorge Luis Borges"},{t:"El cr\xE9dito pertenece al hombre que est\xE1 realmente en la arena, cuyo rostro est\xE1 marcado por el polvo y el sudor del esfuerzo.",a:"Theodore Roosevelt"},{t:"El futuro es algo que alcanza a quien cree en \xE9l antes de verlo.",a:"C. S. Lewis"},{t:"La imaginaci\xF3n es m\xE1s importante que el conocimiento; abraza ambas.",a:"Albert Einstein"},{t:"Haz de tu vida un sue\xF1o, y de tu sue\xF1o una realidad.",a:"Antoine de Saint-Exup\xE9ry"},{t:"Lo que gastas no se pierde; lo que das con amor queda sembrado para siempre.",a:"Madre Teresa"},{t:"Despierta, porque tu estrella ya cruz\xF3 la mitad del cielo.",a:"Yalal ad-Din Rumi"},{t:"Nadie se ba\xF1a dos veces en el mismo r\xEDo.",a:"Her\xE1clito"},{t:"Soy humano y nada de lo humano me resulta ajeno.",a:"Terencio"},{t:"Que cada uno haga lo suyo y vaya a lo suyo, que es el modo m\xE1s seguro de llegar lejos.",a:"Baltasar Graci\xE1n"},{t:"La mente no es un recipiente por llenar, sino un fuego por encender.",a:"Plutarco"},{t:"Venir juntos es el comienzo; mantenerse juntos es el progreso; trabajar juntos es el \xE9xito.",a:"Henry Ford"},{t:"La felicidad es cuando lo que piensas, lo que dices y lo que haces est\xE1n en armon\xEDa.",a:"Mahatma Gandhi"},{t:"Lo que el pueblo necesita es alegr\xEDa y canto.",a:"Violeta Parra"},{t:"Si no puedes volar, corre; si no puedes correr, camina; si no puedes caminar, gatea; pero sea lo que sea, sigue avanzando.",a:"Martin Luther King"},{t:"La libertad es un ejercicio cotidiano o deja de existir.",a:"Mario Benedetti"},{t:"Haz lo que puedas, con lo que tengas, donde est\xE9s.",a:"Theodore Roosevelt"},{t:"De todos los instrumentos, el m\xE1s precioso es el libro, porque los dem\xE1s son extensiones del cuerpo; el libro, de la imaginaci\xF3n y la memoria.",a:"Jorge Luis Borges"},{t:"La paciencia tiene m\xE1s poder que la fuerza.",a:"Plutarco"},{t:"Nadie tan joven con un viejo error, ni tan viejo para un nuevo acierto.",a:"Proverbio irland\xE9s"},{t:"Cada ma\xF1ana nacemos de nuevo; lo que hacemos hoy es lo que m\xE1s importa.",a:"Buda"},{t:"Amar es descubrir que el otro tambi\xE9n tiene un mundo.",a:"Gabriela Mistral"},{t:"Al que madruga, el sol lo acompa\xF1a; al que camina, el camino lo ense\xF1a.",a:"Atahualpa Yupanqui"},{t:"Quien no ha buscado su propio camino repite siempre el camino ajeno.",a:"Rosario Castellanos"},{t:"Es tan corto el amor, y es tan largo el olvido.",a:"Pablo Neruda"},{t:"Solo el que piensa y siente al mismo tiempo puede cambiar el mundo.",a:"Octavio Paz"},{t:"Todo necio confunde valor y precio.",a:"Antonio Machado"},{t:"La vida es la \xFAnica realidad que vale; todo lo dem\xE1s es decoraci\xF3n.",a:"Frida Kahlo"},{t:"Hay que endurecerse, pero sin perder jam\xE1s la ternura.",a:"Ernesto Che Guevara"},{t:"Debes tener caos dentro de ti para dar a luz una estrella danzante.",a:"Friedrich Nietzsche"},{t:"La valent\xEDa consiste en conocer qu\xE9 temer y qu\xE9 no temer.",a:"Plat\xF3n"},{t:"Hay dos maneras de ser feliz en este mundo: una es hacerse el tonto y la otra serlo.",a:"Nicanor Parra"},{t:"Trata de no volverte un hombre de \xE9xito, sino m\xE1s bien un hombre de valor.",a:"Albert Einstein"},{t:"Insiste en ti mismo; nunca imites.",a:"Ralph Waldo Emerson"},{t:"\xC1nimo, que las adversidades fueron puestas en el mundo para prueba de los varones esforzados.",a:"Miguel de Cervantes"},{t:"No podemos todos hacer grandes cosas, pero podemos hacer cosas peque\xF1as con gran amor.",a:"Madre Teresa"},{t:"La perseverancia es lo que convierte los sue\xF1os en realidad.",a:"Sim\xF3n Bol\xEDvar"},{t:"Quien siembra vientos cosecha tormentas; quien siembra bien cosecha paz.",a:"Proverbio hebreo"},{t:"Para llegar lejos no importa la velocidad, sino la direcci\xF3n constante.",a:"An\xF3nimo"},{t:"Utop\xEDa est\xE1 en el horizonte: camino dos pasos, ella se aleja dos pasos. Sirve para eso: para caminar.",a:"Eduardo Galeano"},{t:"En medio de la dificultad reside la oportunidad.",a:"Albert Einstein"}],window.fraseDFT={t:"Hoy el tiempo se detiene para que el alma respire. No es un d\xEDa que se cuenta, es un d\xEDa que se siente: cierra el ciclo con gratitud, suelta lo que ya no sirve y abre el coraz\xF3n al nuevo sol.",a:"D\xEDa Fuera del Tiempo \xB7 20 de junio \xB7 We Tripantu"},window.fraseDelDia=function(e){return window.frases[e%window.frases.length]};
